public class RespondWithPlans {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, Plans plans, Sheets sheets, AsOf asOfSheet,
            ObjectResponse<List<PlanResponse>> response) throws InvalidSheetRequestException {
        response.send(asOfSheet.view(sheetId, asOf,
                () -> {
                    var today = sheets.today(sheetId);
                    return plans.onSheet(sheetId).stream().map(plan -> PlanResponse.from(plan, today)).toList();
                }));
    }
}
package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.util.List;

/** A plan as the screens show it: amounts with two decimals, dates as yyyy-mm-dd; `nextDates` its
 *  first five plan dates after the sheet's today and on or before its end, the paused ones left out;
 *  `paused` whether it is paused now. */
public record PlanResponse(long id, long personId, String amount, String start, Integer every, Integer day, String end,
        int generated, List<String> nextDates, boolean paused) {
    static PlanResponse from(Plan plan, LocalDate today) {
        return new PlanResponse(plan.id(), plan.personId(), plan.amount().toPlainString(), plan.start().toString(),
                plan.every(), plan.day(), plan.end().toString(), plan.generated(),
                plan.nextDates(today, 5).stream().map(LocalDate::toString).toList(), plan.paused());
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** A person's plan: a claim of `amount` on the start date and every `every` days after, or (`every`
 *  null) monthly on `day` of the month, up to the end date; `generated` is how many claims it has
 *  made so far; `pauses` its pauses in the order made, a plan date in one skipped. */
public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
        Integer day, LocalDate end, int generated, List<PlanPause> pauses) {

    /** Whether the plan is paused now: it has a pause not yet resumed. */
    public boolean paused() {
        return pauses.stream().anyMatch(p -> p.resumedOn() == null);
    }

    private boolean skipped(LocalDate date) {
        return pauses.stream().anyMatch(p -> p.skips(date));
    }

    /** The plan dates from the start up to `last`, in order: the start then every N days, or the
     *  day of the month in every month from the start's month (a day beyond the month's length on
     *  its last day), dates before the start and dates in a pause left out. */
    public List<LocalDate> dates(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (every != null) {
            for (LocalDate date = start; !date.isAfter(last); date = date.plusDays(every)) dates.add(date);
        } else {
            for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
                LocalDate date = month.atDay(Math.min(day, month.lengthOfMonth()));
                if (!date.isBefore(start) && !date.isAfter(last)) dates.add(date);
            }
        }
        dates.removeIf(this::skipped);
        return dates;
    }

    /** The first `count` plan dates after `today` and on or before the end, in order. */
    public List<LocalDate> nextDates(LocalDate today, int count) {
        List<LocalDate> next = new ArrayList<>();
        for (LocalDate date : dates(end)) {
            if (next.size() == count) break;
            if (date.isAfter(today)) next.add(date);
        }
        return next;
    }
}
-- A plan's pauses, in the order made: paused on the sheet's today it was paused, resumed on the
-- sheet's today it was resumed (null while it stays paused). A plan date on or after the day paused
-- and before the day resumed is skipped. At most one pause of a plan is open.
CREATE TABLE plan_pause (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL,
    plan_id    BIGINT       NOT NULL REFERENCES plan (id),
    paused_on  DATE         NOT NULL,
    resumed_on DATE
);
CREATE INDEX plan_pause_sheet ON plan_pause (sheet_id, plan_id);

CREATE TABLE asof.plan_pause AS SELECT * FROM public.plan_pause WHERE FALSE;
CREATE TABLE asof_hist.plan_pause AS SELECT * FROM public.plan_pause WHERE FALSE;
ALTER TABLE asof_hist.plan_pause ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.plan_pause ADD COLUMN h_made_on DATE;
ALTER TABLE asof_hist.plan_pause ADD COLUMN h_op CHAR(1) NOT NULL;
CREATE INDEX plan_pause_hist_sheet ON asof_hist.plan_pause (sheet_id, h_seq);
CREATE TRIGGER plan_pause_history AFTER INSERT, UPDATE, DELETE ON public.plan_pause FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';

